// Doeldatum in Europe/Brussels. topic 'yesterday' -> de dag ervoor.
const now = Date.now();
const t = msg.topic === 'yesterday' ? now - 86400000 : now;
const date = new Intl.DateTimeFormat('sv-SE', { timeZone: 'Europe/Brussels' })
    .format(new Date(t)).replaceAll('-', '');
msg.pvDate = date;
msg.method = 'GET';
msg.url = '__PVDIARY_URL__/api/day?date=' + date + '&collector=__COLLECTOR__';
msg.headers = {};
return msg;

// Welke 5-min slots ontbreken vandaag? Bouw daarna de HA-history-URL.
const TZ = 'Europe/Brussels';
function tzOffsetMs(dt) {
    const s = new Intl.DateTimeFormat('en-US', {
        timeZone: TZ, hour12: false, year: 'numeric', month: '2-digit',
        day: '2-digit', hour: '2-digit', minute: '2-digit', second: '2-digit',
    }).format(dt);
    const [dd, tt] = s.split(', ');
    const [mm, da, yy] = dd.split('/');
    return Date.parse(yy + '-' + mm + '-' + da + 'T' + tt.replace('24:', '00:') + 'Z') - dt.getTime();
}
// lokale middernacht van y-m-d als unix-seconden (dst-proof)
function midnight(y, m, d) {
    const guess = Date.UTC(y, m - 1, d, 12, 0, 0);       // middag: nooit een dst-rand
    const off = tzOffsetMs(new Date(guess));
    return (Date.UTC(y, m - 1, d, 0, 0, 0) - off) / 1000;
}

const date = msg.pvDate;
const y = +date.slice(0, 4), m = +date.slice(4, 6), d = +date.slice(6, 8);
const nd = new Date(Date.UTC(y, m - 1, d + 1));
const start = midnight(y, m, d);
const dayEnd = midnight(nd.getUTCFullYear(), nd.getUTCMonth() + 1, nd.getUTCDate());
const end = Math.min(dayEnd, Math.floor(Date.now() / 1000));

const have = new Set(((msg.payload && msg.payload.samples) || []).map((s) => s[0]));
const missing = [];
for (let t = Math.ceil(start / 300) * 300; t < end; t += 300) {
    if (!have.has(t)) missing.push(t);
}
if (!missing.length) {
    node.status({ fill: 'green', shape: 'dot', text: date + ': geen gaten' });
    return null;
}
msg.pvMissing = missing;
msg.method = 'GET';
msg.url = 'http://supervisor/core/api/history/period/'
    + new Date((start - 1800) * 1000).toISOString()
    + '?filter_entity_id=__PV_POWER_ENTITY__'
    + '&end_time=' + new Date((end + 300) * 1000).toISOString()
    + '&minimal_response&no_attributes&significant_changes_only=0';
msg.headers = { Authorization: 'Bearer ' + env.get('SUPERVISOR_TOKEN') };
node.status({ text: date + ': ' + missing.length + ' gaten' });
return msg;

// Vul elk gat met de HA-meting op dat moment. Alleen als we het zeker weten:
// - sensor was live rond dat tijdstip (< 15 min tussen de omliggende metingen)
//   -> laatste bekende waarde
// - anders, als de meting ervoor en erna allebei 0 W was -> 0 W (nacht/uit)
// - anders overslaan; dan lag de bron plat en is de echte waarde onbekend.
const LIVE = 900;
const states = [];
for (const series of (msg.payload || [])) {
    for (const st of series) {
        const t = Math.floor(Date.parse(st.last_updated || st.last_changed) / 1000);
        const v = Number(st.state);
        states.push([t, Number.isFinite(v) ? v : null]);
    }
}
states.sort((a, b) => a[0] - b[0]);

const out = [];
let skipped = 0;
for (const ts of msg.pvMissing) {
    let prev = null, next = null;
    for (const s of states) {
        if (s[0] <= ts) prev = s;
        else { next = s; break; }
    }
    let w = null;
    if (prev && next && prev[1] !== null && next[1] !== null) {
        if (next[0] - prev[0] <= LIVE) w = Math.round(prev[1]);
        else if (prev[1] === 0 && next[1] === 0) w = 0;
    }
    if (w === null) { skipped++; continue; }
    out.push({
        method: 'POST',
        url: '__PVDIARY_URL__/api/ingest/sample',
        headers: { Authorization: 'Bearer __INGEST_TOKEN__', 'Content-Type': 'application/json' },
        payload: { collector: '__COLLECTOR__', ts: ts, power_w: w },
    });
}
node.status({ fill: skipped ? 'yellow' : 'green', shape: 'dot',
    text: msg.pvDate + ': ' + out.length + ' gevuld, ' + skipped + ' onbekend' });
node.warn('pvdiary backfill ' + msg.pvDate + ': ' + out.length + ' gevuld, ' + skipped + ' onbekend');
return [out];
